<?php
require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $db=getDB(); if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf_token']??null)){ $id=(int)post('deposit_id'); $action=(string)post('action'); $s=$db->prepare('SELECT * FROM deposits WHERE id=? AND status="pending"'); $s->execute([$id]); $d=$s->fetch(); if($d){ if($action==='approve'){ $db->beginTransaction(); try{$db->prepare('UPDATE deposits SET status="approved",reviewed_at=NOW() WHERE id=?')->execute([$id]); $db->prepare('UPDATE wallets SET balance=balance+?,updated_at=NOW() WHERE user_id=?')->execute([$d['amount'],$d['user_id']]); addTransaction((int)$d['user_id'],'deposit',(float)$d['amount'],'Deposit approved',$id,'completed'); $db->commit(); flash('success','Deposit approved.');}catch(Throwable $e){$db->rollBack();flash('error','Could not approve deposit.');} } elseif($action==='reject'){$db->prepare('UPDATE deposits SET status="rejected",reviewed_at=NOW() WHERE id=?')->execute([$id]);flash('success','Deposit rejected.');} } redirect(appUrl('admin/deposits.php')); } $rows=$db->query('SELECT d.*,u.username FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.created_at DESC')->fetchAll(); $pageTitle='Deposits';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">REVIEW QUEUE</span><h1>Deposits</h1></div><?php foreach(consumeFlashes() as $f): ?><div class="alert <?= e($f['type']) ?>"><?= e($f['message']) ?></div><?php endforeach; ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $d): ?><tr><td><?= e($d['username']) ?></td><td><?= formatCurrency($d['amount']) ?></td><td><?= e($d['payment_method']) ?></td><td><?= e($d['payment_reference']?:'—') ?></td><td><span class="badge <?= e($d['status']) ?>"><?= e(ucfirst($d['status'])) ?></span></td><td><?php if($d['status']==='pending'): ?><form method="post" class="inline-form"><?= csrfField() ?><input type="hidden" name="deposit_id" value="<?= e($d['id']) ?>"><button name="action" value="approve" class="btn small primary">Approve</button><button name="action" value="reject" class="btn small danger">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
